                BackgroundColor = Color.FromArgb("#E0E0E0")
            };
            _searchBar.TextChanged += OnSearchTextChanged;

            var topBar = new Grid
            {
                ColumnDefinitions = new ColumnDefinitionCollection
                {
                    new ColumnDefinition(GridLength.Star),
                    new ColumnDefinition(GridLength.Auto),
                    new ColumnDefinition(GridLength.Auto)
                },
                ColumnSpacing = 4,
                Padding = new Thickness(4)
            };
            topBar.Add(_rootPicker, 0);
            topBar.Add(backButton, 1);
            topBar.Add(cancelButton, 2);

            Content = new Grid
            {
                RowDefinitions = new RowDefinitionCollection
                {
                    new RowDefinition(GridLength.Auto),    // root picker + buttons
                    new RowDefinition(GridLength.Auto),    // path
                    new RowDefinition(GridLength.Auto),    // search bar
                    new RowDefinition(GridLength.Star),    // file list
                },
                RowSpacing = 2,
                Children =
                {
                    topBar,
                    _pathLabel,
                    _searchBar,
                    _fileList,
                }
            };
            Grid.SetRow(topBar, 0);
            Grid.SetRow(_pathLabel, 1);
            Grid.SetRow(_searchBar, 2);
            Grid.SetRow(_fileList, 3);

            DetectRoots();
        }

