                            miniPreview.Drawable = null;

                            var filePath = fi.FullPath;
                            TagModel? model = null;
                            try
                            {
                                model = await Task.Run(() =>
                                {
                                    using var stream = File.OpenRead(filePath);
                                    return TagParser.ParseLightweight(stream);
                                });
